package android.graphics;public class RectF {public float left,top,right,bottom;public void set(float l,float t,float r,float b){left=l;top=t;right=r;bottom=b;}public RectF(){}public RectF(float l,float t,float r,float b){set(l,t,r,b);}public void set(RectF r){set(r.left,r.top,r.right,r.bottom);}public float width(){return right-left;}public float height(){return bottom-top;}public float centerX(){return (left+right)*.5f;}public float centerY(){return (top+bottom)*.5f;}public void setEmpty(){set(0,0,0,0);}public boolean isEmpty(){return right<=left||bottom<=top;}public void inset(float x,float y){left+=x;right-=x;top+=y;bottom-=y;}public void offset(float x,float y){left+=x;right+=x;top+=y;bottom+=y;}}
